// Test matrix: 3x2 sparse matrix [[1, 2], [3, 0], [0, -4]].
static const std::string expectedGnuplotSparse =
   "#  This file was generated by TNL (www.tnl-project.org)\n"
   "0 0 1\n"
   "1 0 2\n"
   "0 1 3\n"
   "1 2 -4\n";

// The EPS body tracks the position of the last written element and emits the relative
// translation for each nonzero element in the row-major order. The offsets are computed
// with integer arithmetic as ( column - lastColumn ) * elementSize and
// -( row - lastRow ) * elementSize, so a zero offset is printed as "0" (there is no
// negative zero in integer arithmetic) and moving to a lower row gives a negative
// vertical offset.
static const std::string expectedEpsSparse =
   "%!PS-Adobe-2.0 EPSF-2.0\n"
   "%%BoundingBox: 0 0 30 30\n"
   "%%Creator: TNL\n"
   "%%LanguageLevel: 2\n"
   "%%EndComments\n"
   "\n"
   "0 30 translate\n"
   "0 0 translate newpath 0 0 10 10 rectstroke\n"
   "10 0 translate newpath 0 0 10 10 rectstroke\n"
   "-10 -10 translate newpath 0 0 10 10 rectstroke\n"
   "10 -10 translate newpath 0 0 10 10 rectstroke\n"
   "showpage\n"
   "%%EOF\n";

// Test matrix: 3x2 dense matrix [[1, 0], [0, -2], [0.5, 0]].
static const std::string expectedGnuplotDense =
   "#  This file was generated by TNL (www.tnl-project.org)\n"
   "0 0 1\n"
   "1 1 -2\n"
   "0 2 0.5\n";

static const std::string expectedEpsDense =
   "%!PS-Adobe-2.0 EPSF-2.0\n"
   "%%BoundingBox: 0 0 30 30\n"
   "%%Creator: TNL\n"
   "%%LanguageLevel: 2\n"
   "%%EndComments\n"
   "\n"
   "0 30 translate\n"
   "0 0 translate newpath 0 0 10 10 rectstroke\n"
   "10 -10 translate newpath 0 0 10 10 rectstroke\n"
   "-10 -10 translate newpath 0 0 10 10 rectstroke\n"
   "showpage\n"
   "%%EOF\n";

// The MTX size line is composed of std::setw( 9 ) rows, a single space, std::setw( 9 )
// columns, a single space and std::setw( 12 ) nonzero elements count, all right-aligned.
static const std::string expectedMtxBanner = "%%MatrixMarket matrix coordinate real general";
static const std::string expectedMtxSizeLine = "        3         2            4";

// Compare all elements of two host matrices
template< typename Matrix1, typename Matrix2 >
void
expectSameElements( const Matrix1& expected, const Matrix2& actual )
{
   ASSERT_EQ( actual.getRows(), expected.getRows() );
   ASSERT_EQ( actual.getColumns(), expected.getColumns() );
   for( int row = 0; row < expected.getRows(); row++ )
      for( int column = 0; column < expected.getColumns(); column++ )
         EXPECT_EQ( actual.getElement( row, column ), expected.getElement( row, column ) ) << "row = " << row
            << ", column = " << column;
}

template< typename Matrix >
void
test_writeGnuplot()
{
   Matrix matrix( 3, 2 );
   matrix.setElements( { { 0, 0, 1.0 }, { 0, 1, 2.0 }, { 1, 0, 3.0 }, { 2, 1, -4.0 } } );

   std::ostringstream stream;
   TNL::Matrices::MatrixWriter< Matrix >::writeGnuplot( stream, matrix );
   EXPECT_EQ( stream.str(), expectedGnuplotSparse );
}

template< typename Matrix >
void
test_writeEps()
{
   Matrix matrix( 3, 2 );
   matrix.setElements( { { 0, 0, 1.0 }, { 0, 1, 2.0 }, { 1, 0, 3.0 }, { 2, 1, -4.0 } } );

   std::ostringstream stream;
   TNL::Matrices::MatrixWriter< Matrix >::writeEps( stream, matrix );
   EXPECT_EQ( stream.str(), expectedEpsSparse );
}

template< typename Matrix >
void
test_writeMtx()
{
   using HostMatrix = typename Matrix::template Self< typename Matrix::RealType, TNL::Devices::Host >;

   Matrix matrix( 3, 2 );
   matrix.setElements( { { 0, 0, 1.0 }, { 0, 1, 2.0 }, { 1, 0, 3.0 }, { 2, 1, -4.0 } } );

   std::ostringstream stream;
   TNL::Matrices::MatrixWriter< Matrix >::writeMtx( stream, matrix );

   // check the banner line and the size line with exactly derived whitespace
   std::istringstream lines( stream.str() );
   std::string line;
   std::getline( lines, line );
   EXPECT_EQ( line, expectedMtxBanner );
   std::getline( lines, line );  // "%%"
   std::getline( lines, line );  // "%% This file was generated by TNL ..."
   std::getline( lines, line );  // "%% ROWS COLUMNS ELEMENTS"
   std::getline( lines, line );
   EXPECT_EQ( line, expectedMtxSizeLine );

   // round-trip: read the output back and compare element-by-element with the source
   HostMatrix source;
   source = matrix;
   HostMatrix result;
   std::istringstream input( stream.str() );
   TNL::Matrices::MatrixReader< HostMatrix >::readMtx( input, result );
   expectSameElements( source, result );

   // a second, different matrix to avoid a trivial pass
   Matrix matrix2( 2, 5 );
   matrix2.setElements( { { 0, 3, 7.5 }, { 1, 0, -1.0 }, { 1, 4, 2.25 } } );
   std::ostringstream stream2;
   TNL::Matrices::MatrixWriter< Matrix >::writeMtx( stream2, matrix2 );
   HostMatrix source2;
   source2 = matrix2;
   HostMatrix result2;
   std::istringstream input2( stream2.str() );
   TNL::Matrices::MatrixReader< HostMatrix >::readMtx( input2, result2 );
   expectSameElements( source2, result2 );
}

template< typename Matrix >
void
test_writeMtx_storedZeros()
{
   // the element (0,1) is stored explicitly with a zero value and must be skipped by the writer
   Matrix matrix( 3, 3 );
   matrix.setElements( { { 0, 0, 5.0 }, { 0, 1, 0.0 }, { 1, 1, -3.0 }, { 2, 2, 1.0 } } );

   // The explicit zero is really stored in the matrix structure. Note that cross-device
   // copies of sparse matrices drop zero elements (see copySparseToSparseMatrix), so the
   // structure can be checked only for matrices allocated directly on the host.
   if constexpr( std::is_same_v< typename Matrix::DeviceType, TNL::Devices::Host >
                 || std::is_same_v< typename Matrix::DeviceType, TNL::Devices::Sequential > )
   {
      EXPECT_EQ( matrix.getRow( 0 ).getSize(), 2 );
   }
   EXPECT_EQ( matrix.getNonzeroElementsCount(), 3 );

   std::ostringstream stream;
   TNL::Matrices::MatrixWriter< Matrix >::writeMtx( stream, matrix );

   // count the element lines after the 5 header lines - one line per truly nonzero value
   std::istringstream lines( stream.str() );
   std::string line;
   for( int i = 0; i < 5; i++ )
      std::getline( lines, line );
   int elementLines = 0;
   while( std::getline( lines, line ) )
      elementLines++;
   EXPECT_EQ( elementLines, 3 );
}

template< typename Matrix >
void
test_writeGnuplot_dense()
{
   Matrix matrix;
   matrix.setElements( { { 1.0, 0.0 }, { 0.0, -2.0 }, { 0.5, 0.0 } } );

   std::ostringstream stream;
   TNL::Matrices::MatrixWriter< Matrix >::writeGnuplot( stream, matrix );
   EXPECT_EQ( stream.str(), expectedGnuplotDense );
}

template< typename Matrix >
void
test_writeEps_dense()
{
   Matrix matrix;
   matrix.setElements( { { 1.0, 0.0 }, { 0.0, -2.0 }, { 0.5, 0.0 } } );

   std::ostringstream stream;
   TNL::Matrices::MatrixWriter< Matrix >::writeEps( stream, matrix );
   EXPECT_EQ( stream.str(), expectedEpsDense );
}

template< typename Matrix >
void
test_writeGnuplot_verbose()
{
   Matrix matrix( 3, 2 );
   matrix.setElements( { { 0, 0, 1.0 }, { 0, 1, 2.0 }, { 1, 0, 3.0 }, { 2, 1, -4.0 } } );

   // exercises the progress output, the stream content must be the same as without verbose
   std::ostringstream verboseStream;
   TNL::Matrices::MatrixWriter< Matrix >::writeGnuplot( verboseStream, matrix, true );
   EXPECT_EQ( verboseStream.str(), expectedGnuplotSparse );
}

template< typename Matrix >
void
test_writeEps_verbose()
{
   Matrix matrix( 3, 2 );
   matrix.setElements( { { 0, 0, 1.0 }, { 0, 1, 2.0 }, { 1, 0, 3.0 }, { 2, 1, -4.0 } } );

   std::ostringstream verboseStream;
   TNL::Matrices::MatrixWriter< Matrix >::writeEps( verboseStream, matrix, true );
   EXPECT_EQ( verboseStream.str(), expectedEpsSparse );
}

template< typename Matrix >
void
test_writeMtx_verbose()
{
   Matrix matrix( 3, 2 );
   matrix.setElements( { { 0, 0, 1.0 }, { 0, 1, 2.0 }, { 1, 0, 3.0 }, { 2, 1, -4.0 } } );

   std::ostringstream verboseStream;
   TNL::Matrices::MatrixWriter< Matrix >::writeMtx( verboseStream, matrix, true );
   std::ostringstream stream;
   TNL::Matrices::MatrixWriter< Matrix >::writeMtx( stream, matrix );
   EXPECT_EQ( verboseStream.str(), stream.str() );
}

