TEST( MatrixWriterTest, writeGnuplot_file )
{
   using Matrix = SparseMatrix_host;

   Matrix matrix( 3, 2 );
   matrix.setElements( { { 0, 0, 1.0 }, { 0, 1, 2.0 }, { 1, 0, 3.0 }, { 2, 1, -4.0 } } );

   const std::filesystem::path fileName = std::filesystem::temp_directory_path() / "tnl-matrix-writer-test-gnuplot.txt";
   TNL::Matrices::MatrixWriter< Matrix >::writeGnuplot( fileName.string(), matrix );
   std::ifstream file( fileName );
   std::ostringstream content;
   content << file.rdbuf();
   std::filesystem::remove( fileName );
   EXPECT_EQ( content.str(), expectedGnuplotSparse );
}

